export type Vec = number[];
export type Cell = { id: number; x: number; y: number; z: number; color: string; scale?: number };
export type Piece = { id: string; name: string; color: string; cells: Vec[]; pos: Vec };
export type Snapshot = {
  version: number;
  status: string;
  board: Cell[];
  active: Piece | null;
  pending: Piece | null;
  [key: string]: unknown;
};
export type MotionEvent = {
  type: string;
  before: Cell[];
  after: Cell[];
  from: Vec[];
  to: Vec[];
  beforeDims: Vec;
  afterDims: Vec;
  beforeOrientation: Vec[];
  orientation: Vec[];
  axis: number;
  angle: number;
  removed: Cell[];
  added: Cell[];
  combo: number;
  points: number;
  piece: Piece;
  distance: number;
  plane: string;
  direction: number;
};
export class Game {
  constructor(options?: { seed?: number; config?: unknown });
  dims: Vec;
  orientation: Vec[];
  gravity: { axis: number; sign: number };
  board: Cell[];
  active: Piece | null;
  pending: Piece | null;
  held: Piece | null;
  holdUsed: boolean;
  next: Piece[];
  score: number;
  lines: number;
  combo: number;
  bestCombo: number;
  placed: number;
  flipCount: number;
  serial: number;
  status: string;
  readonly fallInterval: number;
  cells(piece?: Piece | null): Vec[];
  ghost(): Vec[];
  move(axis: number, delta: number): boolean;
  rotate(plane: string, direction?: number): boolean;
  tick(): boolean;
  hardDrop(): boolean;
  flipContainer(turn?: string): boolean;
  hold(): boolean;
  revive(): boolean;
  end(): void;
  spawn(piece?: Piece): boolean;
  drainEvents(): MotionEvent[];
  getSnapshot(): Snapshot;
  restore(value: unknown): this;
}
